-- Job analysis
-- -----------------------------------------------------------------------------

create table if not exists public.job_descriptions (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid references public.profiles (id) on delete cascade,
  job_title  text not null default '',
  company    text,
  raw_text   text not null,
  source     text not null default 'paste',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists job_descriptions_user_idx on public.job_descriptions (user_id, created_at desc);

create table if not exists public.job_requirements (
  id                 uuid primary key default gen_random_uuid(),
  job_description_id uuid not null references public.job_descriptions (id) on delete cascade,
  kind               text not null check (kind in (
                       'responsabilite', 'competence-requise', 'competence-appreciee',
                       'langue', 'outil', 'formation', 'experience', 'comportement')),
  label              text not null,
  evidence           text not null default '',
  skill_id           text,
  confidence         numeric(3, 2) not null default 0.50,
  created_at         timestamptz not null default now()
);

create index if not exists job_requirements_description_idx on public.job_requirements (job_description_id, kind);

create table if not exists public.job_analyses (
  id                 uuid primary key default gen_random_uuid(),
  user_id            uuid references public.profiles (id) on delete cascade,
  job_description_id uuid not null references public.job_descriptions (id) on delete cascade,
  extraction         jsonb not null,
  comparison         jsonb,
  answers            jsonb not null default '{}'::jsonb,
  readiness_score    integer check (readiness_score between 0 and 100),
  -- 'rules' or 'rules+ai' — recorded so a user can tell how it was produced.
  engine             text not null default 'rules',
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);

create index if not exists job_analyses_user_idx on public.job_analyses (user_id, created_at desc);

create table if not exists public.skill_gaps (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references public.profiles (id) on delete cascade,
  label       text not null,
  skill_id    text,
  occurrences integer not null default 1,
  status      text not null default 'todo' check (status in ('todo', 'learning', 'addressed')),
  path_id     text,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  unique (user_id, label)
);

