-- -----------------------------------------------------------------------------
-- Feedback and aggregate metrics
-- -----------------------------------------------------------------------------

create table if not exists public.feedback (
  id         uuid primary key default gen_random_uuid(),
  type       text not null check (type in ('idee', 'probleme', 'contenu', 'accessibilite', 'partenariat', 'autre')),
  message    text not null,
  -- Optional and only stored when the user asks for a reply.
  email      text,
  created_at timestamptz not null default now()
);

create index if not exists feedback_created_idx on public.feedback (created_at desc);

-- Counters only. No user id, no session id, nothing that could reconstruct an
-- individual's activity. See docs/PRIVACY.md.
create table if not exists public.metric_counters (
  event      text primary key,
  count      bigint not null default 0,
  updated_at timestamptz not null default now()
);

create or replace function public.increment_metric(metric_event text)
returns void
language sql
security definer
set search_path = public
as $$
  insert into public.metric_counters (event, count, updated_at)
  values (metric_event, 1, now())
  on conflict (event) do update
    set count = public.metric_counters.count + 1,
        updated_at = now();
$$;

-- -----------------------------------------------------------------------------
-- updated_at triggers
-- -----------------------------------------------------------------------------

do $$
declare
  table_name text;
begin
  foreach table_name in array array[
    'sectors', 'skills', 'career_paths', 'roadmap_stages', 'roadmap_items',
    'learning_resources', 'practical_projects', 'interview_questions',
    'content_overrides', 'profiles', 'user_preferences', 'onboarding_responses',
    'profile_skill_assessments', 'user_roadmaps', 'user_notes', 'saved_resources',
    'weekly_plans', 'weekly_tasks', 'user_projects', 'portfolio_entries',
    'job_descriptions', 'job_analyses', 'skill_gaps', 'value_propositions',
    'interview_practice_answers', 'star_examples', 'confidence_work',
    'cv_profiles', 'checklist_states', 'employer_research'
  ]
  loop
    execute format('drop trigger if exists set_updated_at on public.%I', table_name);
    execute format(
      'create trigger set_updated_at before update on public.%I
         for each row execute function public.set_updated_at()',
      table_name
    );
  end loop;
end;
$$;

-- -----------------------------------------------------------------------------
-- Create a profile row automatically for every new auth user.
-- -----------------------------------------------------------------------------

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id, email, display_name)
  values (
    new.id,
    new.email,
    coalesce(new.raw_user_meta_data ->> 'display_name', split_part(new.email, '@', 1))
  )
  on conflict (id) do nothing;

  insert into public.user_preferences (user_id)
  values (new.id)
  on conflict (user_id) do nothing;

  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();
